package com.myeshopping.returnrefundservice.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="return_requests") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class ReturnRequestEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long orderId; @Column(nullable=false) private Long customerId; @Column(nullable=false,length=500) private String reason; @Column(nullable=false) private double amount; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ReturnStatus status; @Column(nullable=false) private LocalDateTime requestedAt; @Column private LocalDateTime completedAt; @PrePersist void prePersist(){requestedAt=LocalDateTime.now();} }
